package main

import (
	"encoding/hex"
	"fmt"

	blazeSDK "github.com/Khysnik/BlazeSDK"
)

func main() {
	cases := []struct{ name, hexStr string }{
		{"INTEGER", "00000005000000090007000000200000da1b35002a"},
		{"STRING", "0000000b000000090007000000200000ba1b65010668656c6c6f00"},
		{"BLOB", "000000090000000900070000002000008acbe20204deadbeef"},
		{"FLOAT", "00000008000000090007000000200000c29fff0a4048f5c3"},
		{"TIMEVALUE", "00000008000000090007000000200000d29b650b80ade204"},
		{"OBJECT_TYPE", "00000006000000090007000000200000bf4e70080401"},
		{"OBJECT_ID", "00000008000000090007000000200000be2a64090401a80f"},
		{"LIST", "00000009000000090007000000200000b29cf4040003010203"},
		{"MAP", "00000013000000090007000000200000b61c3f05010102026100026200026300026400"},
		{"TDF", "0000001d000000090007000000200000c6fcf303c33c3f00a09102c3387f010c686f73742e65612e636f6d0000"},
		{"UNION", "0000000a000000090007000000200000d6ea6e0602b62cbf0007"},
		{"VARIABLE", "0000000e000000090007000000200000da1ca907019213db686c00a30100"},
	}

	for _, value := range cases {
		buf, err := hex.DecodeString(value.hexStr)
		if err != nil {
			fmt.Printf("%-12s bad hex: %v\n", value.name, err)
			continue
		}
		packet, _ := blazeSDK.Fire2Decoder(buf)
		fmt.Printf("%-12s %+v\n", value.name, packet.Payload)
	}

	input, _ := hex.DecodeString("")
	_, dump := blazeSDK.Fire2Decoder(input)
	fmt.Println(dump)

	encodedBytes := blazeSDK.Fire2Encoder(0x0009, 0x0007, 1).
		MsgNum(1).
		String("ASRC", "318307").
		List("CIDS", 0, 30728, 1, 30729, 30730, 30731, 4, 30732, 7, 9, 33, 10, 63490, 403, 13, 15, 30720, 30721, 30722, 30723, 30724, 30725, 30726, 30727).
		String("CLID", "DINGO_COM_BLZ_SERVER").
		BeginStruct("CONF").
		Map("CONF", 1, 1, [][2]interface{}{
			{"associationListSkipInitialSet", "1"},
			{"autoReconnectEnabled", "0"},
			{"cachedUserRefreshInterval", "1s"},
			{"clientUserMetricsUpdateRate", "60000"},
			{"connIdleTimeout", "40s"},
			{"defaultRequestTimeout", "20s"},
			{"maxReconnectAttempts", "30"},
			{"nonResumableTimeoutScale", "2.0"},
			{"nucleusConnect", "https://accounts.ea.com"},
			{"nucleusConnectTrusted", "https://accounts2s.ea.com"},
			{"nucleusPortal", "https://signin.ea.com"},
			{"nucleusProxy", "https://gateway.ea.com"},
			{"pinGameId", "1114185"},
			{"pingPeriod", "20s"},
			{"userManagerMaxCachedUsers", "0"},
			{"voipHeadsetUpdateRate", "1000"},
			{"voipSTTKey", "WyxniILoTMoQmOTt59Fm1UmmgNCGTjHK9IteeBuVmLJW"},
			{"voipSTTProfile", "66307"},
			{"voipSTTUrl", "wss://api.us-east.speech-to-text.watson.cloud.ibm.com/instances/8c634ca8-54fe-4343-9c49-a220abdfaff8/v1/recognize"},
			{"voipTTSKey", "aEGd0oPu7C0rMC68m1LnPPA_spzZxb1G5a0bb8AB1flW"},
			{"voipTTSProvider", "1"},
			{"voipTTSUrl", "https://api.us-east.text-to-speech.watson.cloud.ibm.com/instances/2b0cea2f-92c8-48ab-808d-65d5ed6c7390/v1/synthesize"},
		}).
		EndStruct().
		String("ESRC", "318307").
		List("HPLT", 0, 4, 5, 6, 19, 20, 22, 23, 24).
		String("INST", "dingo-1-steam").
		Integer("LQTK", 0).
		Integer("MAID", 837022840).
		Integer("MINR", 0).
		String("NASP", "steam").
		String("PILD", "").
		String("PLAT", "steam").
		BeginStruct("QOSS").
		Integer("CQFR", 300000000).
		Integer("CQRR", 0).
		Map("LTPS", 1, 3, [][2]interface{}{
			{"gcp-dsm", map[string]interface{}{
				"PSA": "34.58.228.36",
				"PSP": int64(4001),
			}},
			{"gcp-fra", map[string]interface{}{
				"PSA": "34.159.18.119",
				"PSP": int64(4001),
			}},
			{"gcp-sin", map[string]interface{}{
				"PSA": "34.142.164.137",
				"PSP": int64(4001),
			}},
		}).
		BeginStruct("QCNF").
		Integer("DPSP", 4001).
		String("QCA", "qoscoordinator.gameservices.ea.com").
		Integer("QCP", 10010).
		String("QPR", "dingo-1-common").
		EndStruct().
		Integer("SQRR", 15000000).
		Integer("VERS", 1).
		EndStruct().
		String("RELT", "prod").
		String("RSRC", "318307").
		String("SVER", "Blaze 18.3.0 (CL# 2115104)").
		Build()

	fmt.Println(encodedBytes)

	_, dump2 := blazeSDK.Fire2Decoder(encodedBytes)
	fmt.Println(dump2)

	cmpBytes, _ := hex.DecodeString("")
	if d := firstDiff(cmpBytes, encodedBytes); d < 0 {
		fmt.Println("MATCH")
	} else {
		fmt.Printf("MISMATCH at offset %d (0x%X)\n", d, d)
		lo, hi := d-4, d+8
		if lo < 0 {
			lo = 0
		}
		fmt.Printf("  want: % X\n", cmpBytes[lo:min(hi, len(cmpBytes))])
		fmt.Printf("  got:  % X\n", encodedBytes[lo:min(hi, len(encodedBytes))])
		fmt.Printf("  lens: want %d, got %d\n", len(cmpBytes), len(encodedBytes))
	}
}

func firstDiff(diffA, diffB []byte) int {
	n := len(diffA)
	if len(diffB) < n {
		n = len(diffB)
	}
	for i := 0; i < n; i++ {
		if diffA[i] != diffB[i] {
			return i
		}
	}
	if len(diffA) != len(diffB) {
		return n // same prefix, different length
	}
	return -1 // equal
}
